refentry.refsect1:
&reftitle.description;
boolpcntl_async_signals boolnullenable&null;
Если пропущен параметр enable, функция pcntl_async_signals вернёт текущее значение настройки. А если задан, то асинхронная обработка будет включена, либо отключена, в зависимости от заданного значения.

&reftitle.parameters;


  enable



    Включить или отключить асинхронную обработку сигналов.

  &reftitle.examples;

   Пример вызова обработчиков сигналов во время передачи данных cURL

    Без callback-функции прогресса обработчик не вызывался бы до завершения
    передачи данных. Константа CURLOPT_XFERINFOFUNCTION
    доступна начиная с PHP 8.2.0; в более ранних версиях следует использовать
    CURLOPT_PROGRESSFUNCTION.



<?php

pcntl_async_signals(true);

pcntl_signal(SIGALRM, function () {
    echo "Сигнал активности\n";
    pcntl_alarm(1);
});
pcntl_alarm(1);

$ch = curl_init('https://example.com/slow-endpoint');
curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);

// Вызов PHP-кода во время передачи данных позволяет выполниться обработчику
curl_setopt($ch, CURLOPT_NOPROGRESS, false);
curl_setopt($ch, CURLOPT_XFERINFOFUNCTION, function () {
    return 0;
});

$response = curl_exec($ch);
